INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03178', 'Брускетта с ростбифом на бородинском хлебе', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-04', 'Cake&Coffee', 1.000, 'Кусочек бородинского хлеба подсушить на маслом. Ростбиф нарезать тонкими томаты мелко нарезать. Палочки укропа нарезать колечками, залить зеленым маслом.', 'На десертную тарелку нанести немного чесночного крема, на крем положить хлеб, что бы он не катался по тарелке. На хлеб объемно ростбиф, отсадить на ростбиф томаты и колечки укропа, сбрызнуть перцем при необходимости.', 0.15, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 98);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03286', 'Будда боул', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-22', 'Cake&Coffee', 1.000, 'С краю тарелки положить два квадратика нори, на дно тарелки выложить киноа, рядом отсадить морковный хумус, рядом выложить огурцы, чукку, черри половинки. По середине положить половинку яйца в смятку, посыпать его семенами чиа и полить соусом унаги. украсить луком фото в чате.', NULL, 0.252, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 99);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03182', 'Гаспачо', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Кинзу промыть, обсушить, мелко нарезать. Палочки укропа нарезать колечками и залить зеленым маслом.', 'В шляпу налить 250 грамм гаспачо, в центр выложить кинзу, вокруг выложить соломкой нарезаные вяленые томаты. Украсить корзинке.', 0.297, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 100);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03115', 'Глазированая морковь с хумусом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-11', 'Cake&Coffee', 1.000, NULL, 'Семечки подсолнечника', 0.195, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 101);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03168', 'Грибной суп с карамелеированным беконом и чиабаттой', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-29', 'Cake&Coffee', 1.000, 'Лук и шампиньоны (100гр) обжарить на растительном масле, добавить молоко, сливки и картофельное пюре, прогреть и обжарить до коллера. Выложить суп в тарелку, сверху выложить грибы, посыпать грибы карамелизированным беконом.', 'Карамелизированны й бекон', 0.4353, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 102);
