INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03114', 'Котлета из куриной грудки и цукини', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-11', 'Cake&Coffee', 1.000, '140 грамм куриного фарша обжарить до', 'Выложить котлету на тарелку, вокруг отсадить из кондитерского мешка по три капли свекольного и морковного хумуса, выложить гарнир.', 0.165, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 104);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03289', 'Мидии в кокосовом соусе', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-25', 'Cake&Coffee', 1.000, 'Кокосовые сливки и креметту растопить до состояния соуса, добавить мелко нарезанный перец чили. Мидии почистить, отколотые панцири, поместить в соус. Выложить мидии в кострюльку на листья бамбука посыпать пармезаном, украсить ломтиками поджаренной чиабатты и', 'Сыр творожный креметта', 0.56, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 105);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03276', 'Мидии в соусе горганзола', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-19', 'Cake&Coffee', 1.000, 'Лук поррей соломкой слегка обжарить, добавить сливки, сыр с голубой плесенью, подсолить до вкуса.Мидии почистить, отколотые панцири, поместить в соус. креметта Выложить мидии в кострюльку на листья бамбука, полить устричным соусом, ломтиками поджаренной чиабатты и', NULL, 0.435, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 106);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03288', 'Мидии в соусе Том Ям', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-25', 'Cake&Coffee', 1.000, 'В слмвках растворить пасту том ям, прогреть в кипятке, слить воду, удалить Выложить мидии в кострюльку на листья бамбука, полить устричным соусом, накрыть крышкой. подавать с двумя долькой лимона.', NULL, 0.38, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 107);
