INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03429', 'Рамен с креветкой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-15', 'Cake&Coffee', 1.000, 'На дно тарелки выложить отвареную яичную лапшу , по кругу выложить чукку, фасоль, зеленый горошет, обжаренные смятку целиком, залить горячим бульоном, посыпать зеленым луком, перцем. отдельно подать нори, нарезанные на небольшие', 'Фасоль стручковая морожен.', 0.526, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 114);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03275', 'Рамен с курицей', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-19', 'Cake&Coffee', 1.000, 'На дно тарелки выложить отвареную яичную лапшу , по кругу выложить чукку, фасоль, зеленый горошет, нарезанную шампиньоны, яйцо в смятку целиком, залить горячим бульоном, посыпать зеленым луком, перцем. отдельно подать 3х3 см', 'Фасоль стручковая морожен.', 0.576, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 115);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03155', 'Рыбные котлетки', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-14', 'Cake&Coffee', 1.000, 'В рыбный фарш(пикша/лосось обрезь) добавить лук, пюре, соль и перец по вкусу. Сформовать две круглых котлеты, обжарить и допечь в пароконвектомате при 180-200 градусах. Лук кубиком, спаржу поперек тонко, обжарить и добавить сливки, выпарить до загущения.', 'Выложить соус в шляпу, по центру тарелки гарниром - соус в соусничку, котлеты', 0.257, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 116);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03285', 'Салат с уткой', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-22', 'Cake&Coffee', 1.000, 'Айсберг, рукколу, компрессионные огурцы, пекински б/к черри смешать в миске, посолить и выложить на дно тарелки. подогретое филе утки нарибить и выложить на микссалат, по центру выложить половинку яйца в смятку, посыпать его семенами чиа и полить соусом хойсин.', NULL, 0.181, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 117);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03180', 'Сашими из тунца с лаймовой эспумой', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'Сырой тунец нарезать тонко ровными укропа нарезать колечками и залить', 'На плоскую тарелку выложить по центру слайсы туна внахлест, полить соевым соусом и кнужутным маслом, слегка опалить горелкой, ТУНЕЦ ДОЛЖЕН ОСТАТЬСЯ СЫРЫМ, поперчить, в трех местах украсить колечками укропа с лаймовую эспуму в трех местах, сторого Подать незамедлительно.', 0.1021, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 118);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03112', 'Свекольный и морковный хумус с крутонами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-11', 'Cake&Coffee', 1.000, 'Два хумуса отсадить из мешка на ровными горками. посыпать семенами льна и подсолнуха, рядом с хумусом выложить крутоны. Сбрызнуть блюдо зеленым', 'подсолнечника', 0.214, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 119);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03183', 'Соба с тунцом татаки', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Собу положить в кипящую подсоленую воду и варить 3 минуты, после сразу достать из воды. Шампиньоны нашинковать, перец нарезать тонкой соломкой, обжарить, добавить отварную собу и соус унаги, бруском, обжечь горелкой со всех сторон и нарезать вдоль на 4 кусочка.', 'Собу с овощами выложить в шляпу, сверху выложить нарезаный тунец ровно сложенный в нахлест. Посыпать перцем.', 0.197, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 120);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03431', 'Сэндвич бенедикт с индейкой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-16', 'Cake&Coffee', 1.000, NULL, 'завправка Голландез из кремера', 0.251, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 121);
