INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03274', 'Том Ям', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-19', 'Cake&Coffee', 1.000, 'Шампиньоны дольками обжарить, добавить креветки, обжарить. Залить бульоном, добавить рыбный, устричный и том ям соуса, добавить кальмары и мидии, прокипятить. В глубокую белую тарелку положить два листа бамбука, выложить все, кроме мидий и бульона, аккуратно влить бульон, возле торчащих листьев выложить мидии, украсить соломой из порея.', NULL, 0.45, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 123);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03391', 'Большой Завтрак', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-08', 'Cake&Coffee', 1.000, 'выкладка по фото, голландез на яйца, посыпать хрустящим луком', 'Индейка 40 гр Бекон 50гр лосось сс 40гр цукини и болгарский перец по 30гр пармская ветчина 20гр ростбиф мариновонный 40гр Сыр творожный креметта Голландез из кремера', 0.2563, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 124);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03109', 'Большой завтрак с беконом и грибами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-10', 'Cake&Coffee', 1.000, 'Бекон целой полоской и шампиньоны (мелкие на 4 части, крупные на 6) обжарить, подготовить яйцо на выбор гостя, черри целиком, огурец слайсом поперек, Чиабатту жарим на гриле, сливочный сыр и', 'Выкладываем на самую большую тарелку в таком порядке по кругу: Чиабатта, сыр, фасоль, салат, глазированная морковь, яйцо на выбор, в центр тарелки - бекон и грибы. Салат посыпать семенами льна.', 0.4666, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 125);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03162', 'Большой завтрак с горячим росбифом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-18', 'Cake&Coffee', 1.000, 'Росбиф слайсами и шампиньоны(мелкие на подготовить яйцо на выбор гостя, черри целиком, огурец слайсом поперек, Чиабатту жарим на гриле, сливочный сыр и', 'Выкладываем на самую большую тарелку в таком порядке по кругу: Чиабатта, сыр, фасоль, салат, глазированная морковь, яйцо на выбор, в центр тарелки - ростбиф и грибы. Салат посыпаем семенами льна. Говядина внутренняя вырезка', 0.4626, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 126);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03111', 'Большой завтрак с овощами аль дэнтэ', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-11', 'Cake&Coffee', 1.000, 'Цукини дольками, болгарский перец части, крупные на 6) обжарить, подготовить салата рвем руками айсберг, 2 черри оливковое масло + соль и перец. Чиабатту соуснички.', 'Выкладываем на самую большую тарелку в таком порядке по кругу: Чиабатта, сыр, фасоль, салат, глазированная морковь, яйцо на выбор, в центр тарелки -овощи альденте.Салат посыпать семенами льна.', 0.5366, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 127);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00034', 'Глазунья с авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'На холодную сковороду с антипригарным плиту и жарим яйца до готовности так, что Авокадо нарезаем слайсом. Чиабатту', 'На тарелку выкладываем чиабатту и гуакамолле в соусничке, глазунью, рядом авокадо, на авокадо рукколу. сбрызнуть оливковым маслом и посыпать молотым перцем.', 0.2331, 3, 10, 14, 159, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 128);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00035', 'Глазунья с беконом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'На холодную сковороду с антипригарным плиту и жарим яйца до готовности так, что Бекон целыми слайсами обжариваем.', 'На тарелку выкладываем хлеб и сливочный сыр в соусничке, глазунью, сверху айсберг, на айсберг - поджареный бекон. Сбрызгиваем оливковым маслом и посыпаем перцем.', 0.2431, 7, 16, 13, 223, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 129);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01564', 'Драники с беконом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-01-08', 'Cake&Coffee', 1.000, 'Отварной картофель натереть на мелкой терке, добавить яйцо, соль и перец, покрытием три ровных дранника, обжарить до готовности. Бекон поджарить целыми гостя.', 'На плоскую тарелку выложить три дранника внахлест по линии, рядом выложить яйцо, на драники - бекон и рукколу, посыпать', 0.218, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 130);
