INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00036', 'Омлет с авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'На готовый омлет выложить авокадо четвертикнки, листья базилика. Сложить омлет пополам. Чиабатту поджарить на гриле.', 'На тарелку выложить чиабатту и гуакамоле в соусничке, омлет, украсить рукколой и посыпать молотым перцем.', 0.3162, 3, 12, 13, 174, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 133);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00037', 'Омлет с грибами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'На готовый омлет выложить обжаренные грибы и посыпать пармезаном. Сложить омлет пополам. Чиабатту жарим на гриле.', 'На тарелку выкладываем чиабатту и сливочный сыр в соусничке, омлет. Украшаем рукколой, посыпаем молотым Сыр творожный креметта', 0.2887, 6, 12, 11, 168, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 134);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00038', 'Пашот с авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'Пашот сувид 2шт аккуратно разбиваем в прогреться 2-3минуты. Чиабатту жарим на делаем в хлебе ложкой углубление для', 'На тарелку выкладываем рядом друг с другом хлеб со сливочным сыром, в углубления выкладываем пашот, меду пашотом кладем авокадо и рукколу, посыпаем перцем и сбрызгиваем оливковым маслом.', 0.233, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 135);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01569', 'Роял пашот', (SELECT id FROM organizations WHERE name='Бранч'), '2023-05-13', 'Cake&Coffee', 1.000, 'Чиабатту поджарить, намазать сливочным кипящую воду аккуратно разбить 1 яйцо прогреться 2-3минуты.', 'Выложить хлеб со сливочным сыром на плоскую тарелку, в углубдение выложить прогретое яйцо, на яйцо выложить тонко Сыр творожный креметта горелкой. Рядом с хлебом выложить рукколой, посыпать перцем, сбырзнуть', 0.198, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 136);
