INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00046', 'Бруск. с лососем и авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2023-05-13', 'Cake&Coffee', 1.000, 'чиабатту 2шт поджарить на гриле, сделать сливочным сыром. Семгу нарезать тонкими креметта слайсами, авокадо нарезать слайсами.', 'На тарелку выложить два кусочка чиабатты, на творожный сыр выложить рванный айсберг, слайсы авокадо. Сверху ровно выложить слайсированный лосось.', 0.208, 14, 38, 17, 471, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 158);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00045', 'Бруск. с лососем, каперсами и зеленью', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-11', 'Cake&Coffee', 1.000, 'чиабатту 2шт поджарить на гриле, сделать сливочным сыром.', 'Выложить чиабатту на тарелку, посыпать рубленой зеленью, каперсами, выложить лосось, сверху украсить рукколой.', 0.199, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 159);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02811', 'Брускетта с уткой', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-14', 'Cake&Coffee', 1.000, NULL, 'Сыр творожный креметта Свекольный бальзамик', 0.235, 8, 5, 48, 272, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 160);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02999', 'Кесадилья с грибами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Тортилью положить на блинную сковороду, сверху выложить сыр, включить плитку и дождаться, когда тортилья поджарится, на пиццы сыр выложить жаренные шампиньоны, посолить, поперчить, сложить пополам.', 'На тарелку выложить кесадилью, разрезанную пополам и соусничку сметаны.', 0.232, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 161);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00054', 'Кесадилья с курицей', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Тортилью положить на блинную сковороду, сверху выложить сыр, включить плитку и помидор нарезать кубиком и обжарить, посолить, поперчить, добавить тобаско и пиццы горел. Выложить начинку на сыр и свернуть', 'На тарелку выложить сметану в соусничке и кесадилью, разрезанную пополам.', 0.381, 3, 2, 3, 40, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 162);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00055', 'Кесадилья с тунцом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Тортилью положить на блинную сковороду, сверху выложить сыр, включить плитку и дождаться, когда тортилья поджарится. пиццы Огруец нарезать мелким кубиком, смешать с кукурузой, тунцом и майонезом, добавить соль и перец по вкусу. Выложить начинку и', 'На тарелку выложить соус песто в соусничке и кесадилью, разрезаную пополам.', 0.294, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 163);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02331', 'Кесадилья сырная', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Намазать тортилью творожным сыром, креметта посыпать моцареллой, чеддаром, рубленой зеленью, свернуть пополам и поджарить с', 'На тарелку выложить сметану в соусничке и разрезанную пополам кесадилью. Моцарелла для', 0.299, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 164);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01489', 'Тартар из лосося', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'половинку тортильи поджарить на гриле с Лосось, огруец и красный лук нарезать мелким кубиком и смешать с оливковым', 'На плоскую тарелку выложить друг на друга в нахлест тортилью, на нее отсадить из мешка или сделать кнелю из гуакамоле, сверху выложить тартар, посыпать кунжутом и украсить микрозеленью.', 0.18, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 165);
