INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00041', 'Цезарь с курицей', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Айсберг нарвать, смешать с рукколой и майонезом. Грудку су вид поджарить и прогреть на сковороде на купаже посолить, поперчить.', 'В шляпу выложить микс салат, три черри по краям, посыпать пармезаном, сверху выложить куриную грудку, нарезанную под углом 45 на 4-5 частей, положить два крутона.', 0.327, 12, 4, 1, 88, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 177);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02006', 'Цезарь с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Айсберг нарвать, смешать с рукколой и', 'Микс салат выложить в шляпу, три черри целиком по краям, микс посыпать пармезаном, сверху выложить слайсы слабосоленого лосося объемно, рядом положить два крутона.', 0.2646, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 178);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02374', 'Шеф-салат с ростбифом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Шампиньоны(крупно) и ростбиф обжарить. вырезка Огурец слайсом, черри пополам, смешать с', 'Выложить микс салат с овощами в шляпу, сверху выложить жаренные шампы и ростбиф.', 0.182, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 179);
