INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00051', 'Паста с беконом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-01', 'Cake&Coffee', 1.000, 'Обжарить лук, бекон и чеснок, добавит вино и выпарить, добавить сливки и пасту, довести до вкуса солью и перцем.', 'Аккуратно выложить в шляпу, поперчить.', 0.2361, 14, 24, 41, 437, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 188);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00052', 'Паста с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-01', 'Cake&Coffee', 1.000, 'Обжарить лук, чеснок и лосось с/с пластиками, добавить вино и выпарить, добавить сливки и пасту, довести до вкуса', 'Аккуратно выложить в шляпу, поперчить.', 0.2444, 14, 32, 45, 525, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 189);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03161', 'Паста с томленой говядиной и овощами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-18', 'Cake&Coffee', 1.000, 'Нарезать лук кубиком, цукини и телячьи щечки соломкой. Обжарить лук, добавить цукини, щеки, щечный соус и сливки. В готовый соус добавить отваренную пасту, соль, перец.', 'Выложить в шляпу, украсить мелкорезанным зеленым луком.', 0.2683, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 190);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01133', 'Горячий ростбиф с картофелем', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-09', 'Cake&Coffee', 1.000, 'Ростбиф сувидированный обжарить на растительном масле, добавить сливочное дольками обжарить вместе, посолить, поперчить.', 'Выложить гарнир в шляпу, ростбиф нарезать на три части под прямым углом, выложить на гарнир внахлест.поперчить и посолить мясо, украсить микрозеленью.', 0.3525, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 191);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01129', 'Кур. грудка с овощами альденте', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-09', 'Cake&Coffee', 1.000, 'Моцареллу нарезать мелким кубиком, Начинка д/куриной нарубить, все смешать и заправить поместить начинку в карман, обжарить нарезать дольками, болгарский перец дольками. Обжарить овощи до альдэнтэ, посолить, поперчить.', 'На плоскую тарелку выложить овощи по линии, рядом - грудку, украсить черри, разрезанной пополам и соцветием базилика.', 0.33, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 192);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01726', 'Телячьи щечки', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-19', 'Cake&Coffee', 1.000, 'Пюре выкладываем в глубокую тарелку щеки выкладываем на кнели, посыпаем', 'Если щеки подаются с другим гарниром - соус в соусничку.', 0.108, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 193);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02705', 'Филе куриное су вид с цукини', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-09', 'Cake&Coffee', 1.000, 'Куриную грудку сувид обжарить на треугольника. Цукини и морковь нарезать бруском, морковь бланшировать и обжарить', 'Выложить в шляпу гарнир, на гарнир куриную грудку внахлест, посолить, поперчить, украситьь микрозеленью.', 0.286, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 194);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00995', 'Пицца Маргарита', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Раскатать круг теста ~33 см, смазать посыпать тертой моцареллой, запечь в выложить на пергамент, нарезать на 6 украсить соцветием базилика.', 'Тесто не должно подгореть!', 0.381, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 195);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02040', 'Пицца Пепперони', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Собрать маргариту; Выложить тонко наслайсированную пепперони; Запечь в пиццепечи; Нарезать на 6 кусочков.', 'Тесто не должно подгореть!', 0.4031, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 196);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02978', 'Пицца с беконом', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Собрать маргориту; Бекон нарезать курпными квадратами, маслины нарезать кольцами, выложить на Запечь в пиццепечи, украсить петрушкой, пиццы нарезать на 6 кусочков.', 'Тесто не должно подгореть!', 0.459, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 197);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02977', 'Пицца с курицей и грибами', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Собрать маргориту; Курицу и грибы нарезать слайсами, выложить на пиццу; Запечь в пиццепечи, нарезать на 6 кусочков; пиццы Украсить петрушкой и кунжутом.', 'Тесто не должно подгореть!', 0.482, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 198);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00991', 'Пицца с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-01', 'Cake&Coffee', 1.000, 'Собрать маргориту; Выложить 6 шариков из творожного сыра; Запечь в пиццепечи; пиццы Нарезать на 6 кусочков; Нарезать 6 пластиков семги по 10 грамм и выложить по пластику на каждый шарик креметта Посыпать петрушкой и кунжутом.', 'тесто не должно подгореть! ПЛАСТИКИ СЕМГИ ДОЛЖНЫ БЫТЬ РОВНЫЕ И КРАСИВЫЕ!', 0.5516, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 199);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00996', 'Пицца с пармой', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-01', 'Cake&Coffee', 1.000, 'Собрать и выпечь маргориту; Нарезать на 6 кусочков; на каждый кусочек выложитьвяленые четвертинки; пиццы украсить рукколой; сверху на рукколу выложить тонко', 'Тесто не должно подгореть!', 0.4542, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 200);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00992', 'Пицца сырная', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Раскатать тесто ~33 см, смазать сливками; кусочками и выложить на сливки; Посыпать моцареллой и выложить пластики чеддара; пиццы Выпечь в пиццепечи; Нарезать на 6 кусочков, украсить соцветием', 'Сыр творожный креметта', 0.3456, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 201);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01721', 'Фокачча', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-19', 'Cake&Coffee', 1.000, '130 грамм теста раскатать в круг ~20 см, сделать несколько дырок, выпечь в пиццепечи, смазать готовую лепешку соусом песто, нарезать на 4 части.', NULL, 0.135, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 202);
