INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03221', 'Сырники с облепиховой сгущенкой', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Обжарить три сырника.', 'сгущенка Сырники выложить на большую плоскую тарелку в линию, посыпать пудрой и слегка общечь горелкой, для придания карамельной корочки, рядом с сырниками отсадить сметану из кремера, полить вокруг', 0.27, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 348);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03218', 'Телячьи щеки с птитимом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Шеки 80 грамм одним куском прогреть в смазав маслом. должен хорошо выпариться)', 'в центр большой плоской тарелки выложить щеку, украсить микрозеленью(мелкой) и', 0.184, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 349);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03216', 'Томатный суп с чикенболами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Куриный фарш обжарить неровными томатного соуса и прогреть.', 'Вылить суп в тарелку, выложить кинзу, сбрызнуть зеленым маслом. Перец консерв. отдельно подать крутоны, сметану и Халапеньо халапеньо.', 0.39, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 350);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03224', 'Чай "Яблоко с карамелью" 300', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-27', 'Cake&Coffee', 1.000, NULL, 'Апельсин нарезать кружками и выдавиь сок,яблоко нарезать полукольцами. Добавиь сироп и чай. Добавить кипятка и вскипятить.', 0.1125, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 351);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03223', 'Чай "Яблоко с карамелью" 600', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-27', 'Cake&Coffee', 1.000, NULL, 'Апельсин нарезать кружками и выдавиь сок,яблоко нарезать полукольцами. Добавиь сироп и чай. Добавить кипятка и вскипятить.', 0.115, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 352);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03215', 'Шакшука', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Томатный соус и яйца пашот прогреть.', 'В белую глубокую тарелку аккуратно выложить соус, в центр 2 яйца. Украсить обильно кинзой, сбрызнуть зеленым Перец консерв. Халапеньо крутоны и халапеньо в соусничке.', 0.3, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 353);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03445', 'Овсяная каша с медовой грушой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-27', 'Cake&Coffee', 1.000, 'Овсяную кашу сварить на воде с солью и сердцевину, мед развести с небольшим в вакуумный покет и завакуумировать, кашу выложить в большую глубокую белую сахарной пудрой и обжечь горелкой до корочки, выложить в центр тарелки и посыпать кашу жареными лепестками', NULL, 0.442, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 354);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03447', 'Печеные овощи с тофу сметаной', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-27', 'Cake&Coffee', 1.000, 'Томат запечь при 160 целиком, цукини нарезать длинными дольками, болгарский пере длинными треугольниками, шампиньон пополам, все овощи обжарить на масле с добавлением чеснока, тимьяна. выложить на большую плоскую белую тарелку, отсадить три капли тофу сметаны, сбрызнуть зеленым маслом.', NULL, 0.3383, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 355);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03444', 'Печеный картофель с грибной икрой и тофу сметаной', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-27', 'Cake&Coffee', 1.000, 'Картофель помыть, запечь его в кожуре в фольге, грибы обжарить с луком, посолить, поперчить и пробить блендером до тарелки выложить грибную икру, и выложить сверху на икру, полить тофу сметаной, сбрызнуть зеленым маслом и посыпать МЕЛКО нарезанными ножками', NULL, 0.3623, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 356);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03446', 'Соба с овощами и соусом хойсин', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-27', 'Cake&Coffee', 1.000, 'Собу отварить 3 минуты, овощи нарезать тонокой соломкой и слегка обжарить, добавить собу к овощам, добавить соус хойсин, прогреть. Выложить на большую глубокую белую тарелку и посыпать', NULL, 0.231, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 357);
