DROP TABLE IF EXISTS card_ingredients CASCADE;
DROP TABLE IF EXISTS tech_cards CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS organizations CASCADE;

CREATE TABLE organizations (
    id   SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL UNIQUE
);

CREATE TABLE products (
    id   SERIAL PRIMARY KEY,
    name VARCHAR(500) NOT NULL UNIQUE
);

CREATE TABLE tech_cards (
    id                   SERIAL PRIMARY KEY,
    card_number          VARCHAR(20) NOT NULL UNIQUE,
    dish_name            TEXT NOT NULL,
    organization_id      INT REFERENCES organizations(id),
    approval_date        DATE,
    application_area     VARCHAR(255),
    portion_norm         NUMERIC(10,3) DEFAULT 1000,
    technology           TEXT,
    serving_requirements TEXT,
    total_output_kg      NUMERIC(12,4),
    proteins_per_100g    NUMERIC(6,1),
    fats_per_100g        NUMERIC(6,1),
    carbs_per_100g       NUMERIC(6,1),
    calories_per_100g    NUMERIC(8,1),
    note                 TEXT,
    source_page          INT,
    created_at           TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE card_ingredients (
    id              SERIAL PRIMARY KEY,
    card_id         INT NOT NULL REFERENCES tech_cards(id) ON DELETE CASCADE,
    product_id      INT REFERENCES products(id),
    line_number     INT,
    gross_weight_g  NUMERIC(10,3),
    net_weight_g    NUMERIC(10,3),
    output_g        NUMERIC(10,3),
    gross_weight_kg NUMERIC(10,4),
    net_weight_kg   NUMERIC(10,4),
    output_kg       NUMERIC(10,4)
);

-- Индексы
CREATE INDEX idx_tc_name ON tech_cards(dish_name);
CREATE INDEX idx_tc_date ON tech_cards(approval_date);
CREATE INDEX idx_ci_card ON card_ingredients(card_id);
CREATE INDEX idx_ci_prod ON card_ingredients(product_id);

-- Полнотекстовый поиск
ALTER TABLE tech_cards ADD COLUMN search_vector TSVECTOR;
CREATE INDEX idx_tc_fts ON tech_cards USING GIN(search_vector);

CREATE OR REPLACE FUNCTION f_tc_fts() RETURNS trigger AS $$
BEGIN
    NEW.search_vector := to_tsvector('russian', COALESCE(NEW.dish_name,''));
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS t_tc_fts ON tech_cards;
CREATE TRIGGER t_tc_fts
    BEFORE INSERT OR UPDATE ON tech_cards
    FOR EACH ROW EXECUTE FUNCTION f_tc_fts();

