-- ====== VIEWS ======

CREATE OR REPLACE VIEW v_ttk_full AS
SELECT tc.card_number, tc.dish_name, o.name AS organization,
       tc.approval_date, tc.application_area, tc.technology,
       tc.serving_requirements, tc.total_output_kg,
       tc.proteins_per_100g, tc.fats_per_100g,
       tc.carbs_per_100g, tc.calories_per_100g,
       p.name AS product_name, ci.line_number,
       ci.net_weight_g, ci.output_g
FROM tech_cards tc
LEFT JOIN organizations o ON o.id = tc.organization_id
LEFT JOIN card_ingredients ci ON ci.card_id = tc.id
LEFT JOIN products p ON p.id = ci.product_id
ORDER BY tc.card_number, ci.line_number;

CREATE OR REPLACE VIEW v_nutrition AS
SELECT card_number, dish_name,
       proteins_per_100g AS белки, fats_per_100g AS жиры,
       carbs_per_100g AS углеводы, calories_per_100g AS ккал
FROM tech_cards WHERE calories_per_100g > 0 ORDER BY dish_name;

CREATE OR REPLACE VIEW v_card_stats AS
SELECT tc.card_number, tc.dish_name,
       COUNT(ci.id) AS ingredient_count,
       ROUND(SUM(ci.net_weight_g)::numeric, 1) AS total_net_weight_g,
       tc.total_output_kg, tc.calories_per_100g
FROM tech_cards tc
LEFT JOIN card_ingredients ci ON ci.card_id = tc.id
GROUP BY tc.id ORDER BY tc.card_number;

UPDATE tech_cards SET search_vector = to_tsvector('russian', COALESCE(dish_name,''));

